selection_review=[
 {'pages':[3,4,16],'wording':'any five / any three questions','classification':'exam-level-selection','reason':'All ten questions retained for practice.'},
 {'pages':[7,21],'wording':'or otherwise','classification':'method-choice','reason':'Alternative methods for one required task, not a finite choice of questions.'},
 {'pages':[6],'wording':'a pair of real values','classification':'open-answer','reason':'One pair satisfying the log identity, not a finite list of choices.'},
 {'pages':[27],'wording':'one similarity and one difference','classification':'required-headings','reason':'Two required aspects of one holistic 5-mark comparison; no finite alternatives printed.'},
]
def classify(c):
 t=c['context'].lower()
 if 'questions' in t and 'any' in t:return ('exam-level-selection','All questions retained irrespective of exam selection.')
 if 'otherwise' in t:return ('method-choice','Alternative methods for one required task.')
 return None
if __name__=='__main__':p.write(selection_review,classify)
